DELIMITER $$
--
-- Procedimientos
--
CREATE DEFINER=`root`@`localhost` PROCEDURE `BuscarActivos` (IN `p_categoria_id` INT, IN `p_subcategoria_id` INT, IN `p_busqueda` VARCHAR(255), IN `p_tipo_activo` VARCHAR(100), IN `p_limite` INT)   BEGIN
    DECLARE v_limite INT DEFAULT 20;
    
    IF p_limite IS NOT NULL AND p_limite > 0 THEN
        SET v_limite = p_limite;
    END IF;
    
    SELECT 
        id,
        serial,
        nombre,
        marca_id,
        modelo_id,
        marca_nombre,
        modelo_nombre,
        tipo_activo,
        display_text,
        categoria_id,
        subcategoria_id,
        area_nombre,
        ubicacion_nombre
    FROM vista_activos_busqueda
    WHERE 
        (p_categoria_id IS NULL OR categoria_id = p_categoria_id)
        AND (p_subcategoria_id IS NULL OR subcategoria_id = p_subcategoria_id)
        AND (p_tipo_activo IS NULL OR tipo_activo LIKE CONCAT('%', p_tipo_activo, '%'))
        AND (
            p_busqueda IS NULL 
            OR p_busqueda = '' 
            OR search_text LIKE CONCAT('%', p_busqueda, '%')
        )
    ORDER BY 
        CASE 
            WHEN serial LIKE CONCAT(p_busqueda, '%') THEN 1
            WHEN nombre LIKE CONCAT(p_busqueda, '%') THEN 2
            WHEN serial LIKE CONCAT('%', p_busqueda, '%') THEN 3
            WHEN nombre LIKE CONCAT('%', p_busqueda, '%') THEN 4
            ELSE 5
        END,
        nombre, serial
    LIMIT v_limite;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `ObtenerEstadisticasTickets` ()   BEGIN
    SELECT 'ESTADÍSTICAS DE TICKETS' as titulo;
    
    SELECT 
        'Correctivos' as tipo,
        estado,
        COUNT(*) as cantidad
    FROM correctivos 
    GROUP BY estado
    
    UNION ALL
    
    SELECT 
        'Preventivos' as tipo,
        estado,
        COUNT(*) as cantidad
    FROM preventivos 
    GROUP BY estado
    
    ORDER BY tipo, cantidad DESC;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `ObtenerEstadisticasUsuarios` ()   BEGIN
    SELECT 'DISTRIBUCIÓN POR NIVEL' as categoria;
    
    SELECT 
        nivel,
        estado,
        COUNT(*) as cantidad
    FROM usuarios 
    GROUP BY nivel, estado
    ORDER BY nivel DESC, estado;
    
    SELECT 'USUARIOS MÁS ACTIVOS' as categoria;
    
    SELECT 
        u.nombre,
        u.usuario,
        u.nivel,
        (SELECT COUNT(*) FROM correctivos WHERE asignado_a = u.id OR responsable = u.id) +
        (SELECT COUNT(*) FROM preventivos WHERE asignado_a = u.id OR responsable = u.id) as total_tickets
    FROM usuarios u
    WHERE u.estado = 'Activo'
    HAVING total_tickets > 0
    ORDER BY total_tickets DESC
    LIMIT 10;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `ObtenerTicketsPorUsuario` (IN `usuario_id` INT)   BEGIN
    SELECT 
        'Correctivo' as tipo,
        id,
        titulo,
        estado,
        prioridad,
        fecha_creacion
    FROM correctivos 
    WHERE asignado_a = usuario_id OR responsable = usuario_id
    
    UNION ALL
    
    SELECT 
        'Preventivo' as tipo,
        id,
        titulo,
        estado,
        'Media' as prioridad,
        fecha_creacion
    FROM preventivos 
    WHERE asignado_a = usuario_id OR responsable = usuario_id
    
    ORDER BY fecha_creacion DESC;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `ValidarIntegridadDatos` ()   BEGIN
    SELECT 'VALIDACIÓN DE INTEGRIDAD' as titulo;
    
    -- Usuarios sin email válido
    SELECT 'Usuarios sin email válido' as problema, COUNT(*) as cantidad
    FROM usuarios 
    WHERE email IS NULL OR email = '' OR email NOT LIKE '%@%';
    
    -- Correctivos sin cliente
    SELECT 'Correctivos sin cliente asignado' as problema, COUNT(*) as cantidad
    FROM correctivos 
    WHERE cliente_id IS NULL;
    
    -- Usuarios asignados que no existen
    SELECT 'Correctivos con usuario asignado inexistente' as problema, COUNT(*) as cantidad
    FROM correctivos c
    LEFT JOIN usuarios u ON c.asignado_a = u.id
    WHERE c.asignado_a IS NOT NULL AND u.id IS NULL;
    
    -- Proveedores sin contacto
    SELECT 'Proveedores sin información de contacto' as problema, COUNT(*) as cantidad
    FROM proveedores 
    WHERE (telefono IS NULL OR telefono = '') AND (email IS NULL OR email = '');
END$$

DELIMITER ;

