CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vista_activos_busqueda`  AS SELECT `a`.`id` AS `id`, `a`.`serial` AS `serial`, `a`.`serial_2` AS `serial_2`, `a`.`nombre` AS `nombre`, `a`.`descripcion` AS `descripcion`, `a`.`marca_id` AS `marca_id`, `a`.`modelo_id` AS `modelo_id`, `a`.`ubicacion_id` AS `ubicacion_id`, `a`.`area_id` AS `area_id`, `a`.`tipo_activo` AS `tipo_activo`, `a`.`estado_activo` AS `estado_activo`, `a`.`categoria_id` AS `categoria_id`, `a`.`subcategoria_id` AS `subcategoria_id`, `a`.`cliente_id` AS `cliente_id`, `a`.`proyecto_id` AS `proyecto_id`, `m`.`nombre` AS `marca_nombre`, `mo`.`nombre` AS `modelo_nombre`, `u`.`nombre` AS `ubicacion_nombre`, `ar`.`nombre` AS `area_nombre`, `c`.`nombre` AS `categoria_nombre`, `s`.`nombre` AS `subcategoria_nombre`, `cl`.`nombre` AS `cliente_nombre`, `p`.`nombre` AS `proyecto_nombre`, concat(`a`.`serial`,' - ',`a`.`nombre`) AS `display_text`, concat(coalesce(`a`.`serial`,''),' ',coalesce(`a`.`nombre`,''),' ',coalesce(`m`.`nombre`,''),' ',coalesce(`mo`.`nombre`,''),' ',coalesce(`a`.`tipo_activo`,'')) AS `search_text` FROM ((((((((`activos` `a` left join `marcas` `m` on(`a`.`marca_id` = `m`.`id`)) left join `modelos` `mo` on(`a`.`modelo_id` = `mo`.`id`)) left join `ubicaciones` `u` on(`a`.`ubicacion_id` = `u`.`id`)) left join `areas` `ar` on(`a`.`area_id` = `ar`.`id`)) left join `categorias` `c` on(`a`.`categoria_id` = `c`.`id`)) left join `subcategorias` `s` on(`a`.`subcategoria_id` = `s`.`id`)) left join `clientes` `cl` on(`a`.`cliente_id` = `cl`.`id`)) left join `proyectos` `p` on(`a`.`proyecto_id` = `p`.`id`)) WHERE `a`.`activo` = 1 AND `a`.`estado_activo` = 'ACTIVO' ORDER BY `a`.`nombre` ASC, `a`.`serial` ASC ;

