--
DROP TABLE IF EXISTS `vista_tickets_completa`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vista_tickets_completa`  AS SELECT 'correctivo' AS `tipo_ticket`, `c`.`id` AS `id`, `c`.`titulo` AS `titulo`, `c`.`descripcion` AS `descripcion`, `c`.`solicitante` AS `solicitante`, `c`.`cc` AS `cc`, `c`.`estado` AS `estado`, `c`.`prioridad` AS `prioridad`, `c`.`fecha_creacion` AS `fecha_creacion`, `c`.`fecha_resolucion` AS `fecha_resolucion`, `c`.`horas_trabajadas` AS `horas_trabajadas`, `c`.`fuera_servicio` AS `fuera_servicio`, `c`.`atencion` AS `atencion`, `cl`.`nombre` AS `cliente`, `p`.`nombre` AS `proyecto`, `cat`.`nombre` AS `categoria`, `sub`.`nombre` AS `subcategoria`, `u`.`nombre` AS `ubicacion`, `a`.`nombre` AS `area`, `d`.`nombre` AS `departamento`, `pr`.`nombre` AS `proveedor`, `pr`.`encargado` AS `proveedor_encargado`, `pr`.`telefono` AS `proveedor_telefono`, `t`.`nombre` AS `tipo`, `st`.`nombre` AS `subtipo`, `m`.`nombre` AS `marca`, `mo`.`nombre` AS `modelo`, `us1`.`nombre` AS `asignado_a_nombre`, `us1`.`usuario` AS `asignado_a_usuario`, `us2`.`nombre` AS `responsable_nombre`, `us2`.`usuario` AS `responsable_usuario`, `c`.`contacto` AS `contacto`, `c`.`resolucion` AS `resolucion`, `c`.`reporte_servicio` AS `reporte_servicio`, `c`.`componente` AS `componente` FROM ((((((((((((((`correctivos` `c` left join `clientes` `cl` on(`c`.`cliente_id` = `cl`.`id`)) left join `proyectos` `p` on(`c`.`proyecto_id` = `p`.`id`)) left join `categorias` `cat` on(`c`.`categoria_id` = `cat`.`id`)) left join `subcategorias` `sub` on(`c`.`subcategoria_id` = `sub`.`id`)) left join `ubicaciones` `u` on(`c`.`ubicacion_id` = `u`.`id`)) left join `areas` `a` on(`c`.`area_id` = `a`.`id`)) left join `departamentos` `d` on(`c`.`departamento_id` = `d`.`id`)) left join `proveedores` `pr` on(`c`.`proveedor_id` = `pr`.`id`)) left join `tipos` `t` on(`c`.`tipo_id` = `t`.`id`)) left join `subtipos` `st` on(`c`.`subtipo_id` = `st`.`id`)) left join `marcas` `m` on(`c`.`marca_id` = `m`.`id`)) left join `modelos` `mo` on(`c`.`modelo_id` = `mo`.`id`)) left join `usuarios` `us1` on(`c`.`asignado_a` = `us1`.`id`)) left join `usuarios` `us2` on(`c`.`responsable` = `us2`.`id`))union all select 'preventivo' AS `tipo_ticket`,`pr`.`id` AS `id`,`pr`.`titulo` AS `titulo`,`pr`.`descripcion` AS `descripcion`,`pr`.`solicitante` AS `solicitante`,NULL AS `cc`,`pr`.`estado` AS `estado`,'Media' AS `prioridad`,`pr`.`fecha_creacion` AS `fecha_creacion`,NULL AS `fecha_resolucion`,0 AS `horas_trabajadas`,0 AS `fuera_servicio`,'En Sitio' AS `atencion`,`cl`.`nombre` AS `cliente`,`p`.`nombre` AS `proyecto`,`cat`.`nombre` AS `categoria`,`sub`.`nombre` AS `subcategoria`,`u`.`nombre` AS `ubicacion`,`a`.`nombre` AS `area`,`d`.`nombre` AS `departamento`,`prov`.`nombre` AS `proveedor`,`prov`.`encargado` AS `proveedor_encargado`,`prov`.`telefono` AS `proveedor_telefono`,`t`.`nombre` AS `tipo`,`st`.`nombre` AS `subtipo`,`m`.`nombre` AS `marca`,`mo`.`nombre` AS `modelo`,`us1`.`nombre` AS `asignado_a_nombre`,`us1`.`usuario` AS `asignado_a_usuario`,`us2`.`nombre` AS `responsable_nombre`,`us2`.`usuario` AS `responsable_usuario`,`pr`.`contacto` AS `contacto`,NULL AS `resolucion`,NULL AS `reporte_servicio`,NULL AS `componente` from ((((((((((((((`preventivos` `pr` left join `clientes` `cl` on(`pr`.`cliente_id` = `cl`.`id`)) left join `proyectos` `p` on(`pr`.`proyecto_id` = `p`.`id`)) left join `categorias` `cat` on(`pr`.`categoria_id` = `cat`.`id`)) left join `subcategorias` `sub` on(`pr`.`subcategoria_id` = `sub`.`id`)) left join `ubicaciones` `u` on(`pr`.`ubicacion_id` = `u`.`id`)) left join `areas` `a` on(`pr`.`area_id` = `a`.`id`)) left join `departamentos` `d` on(`pr`.`departamento_id` = `d`.`id`)) left join `proveedores` `prov` on(`pr`.`proveedor_id` = `prov`.`id`)) left join `tipos` `t` on(`pr`.`tipo_id` = `t`.`id`)) left join `subtipos` `st` on(`pr`.`subtipo_id` = `st`.`id`)) left join `marcas` `m` on(`pr`.`marca_id` = `m`.`id`)) left join `modelos` `mo` on(`pr`.`modelo_id` = `mo`.`id`)) left join `usuarios` `us1` on(`pr`.`asignado_a` = `us1`.`id`)) left join `usuarios` `us2` on(`pr`.`responsable` = `us2`.`id`))  ;

