--
-- Estructura para la vista `vista_usuarios_hsf`
--
DROP TABLE IF EXISTS `vista_usuarios_hsf`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vista_usuarios_hsf`  AS SELECT `u`.`id` AS `id`, `u`.`usuario` AS `usuario`, `u`.`nombre` AS `nombre`, `u`.`email` AS `email`, `u`.`telefono` AS `telefono`, `u`.`cargo` AS `cargo`, `u`.`nivel` AS `nivel`, `u`.`estado` AS `estado`, `u`.`fecha_creacion` AS `fecha_creacion`, CASE WHEN `u`.`nivel` = 'Directores / Gerentes' THEN 'Administrador' WHEN `u`.`nivel` = 'Ingenieros / Tecnicos' THEN 'Técnico' WHEN `u`.`nivel` = 'Clientes CEMI' THEN 'Cliente Premium' WHEN `u`.`nivel` = 'Cliente SYM' THEN 'Cliente Básico' ELSE 'Usuario Estándar' END AS `tipo_acceso`, CASE WHEN `u`.`cargo` like '%Director%' OR `u`.`cargo` like '%Gerente%' OR `u`.`cargo` like '%Jefe%' THEN 'Directivo' WHEN `u`.`cargo` like '%Coordinador%' OR `u`.`cargo` like '%Supervisor%' THEN 'Supervisor' WHEN `u`.`cargo` like '%Técnico%' OR `u`.`cargo` like '%Analista%' THEN 'Técnico' WHEN `u`.`cargo` like '%Enfermera%' OR `u`.`cargo` like '%Médico%' THEN 'Salud' WHEN `u`.`cargo` like '%Auxiliar%' OR `u`.`cargo` like '%Secretaria%' THEN 'Apoyo' ELSE 'Operativo' END AS `categoria_cargo`, (select count(0) from `correctivos` where `correctivos`.`asignado_a` = `u`.`id`) AS `correctivos_asignados`, (select count(0) from `preventivos` where `preventivos`.`asignado_a` = `u`.`id`) AS `preventivos_asignados`, (select count(0) from `correctivos` where `correctivos`.`responsable` = `u`.`id`) AS `correctivos_responsable`, (select count(0) from `preventivos` where `preventivos`.`responsable` = `u`.`id`) AS `preventivos_responsable` FROM `usuarios` AS `u` WHERE `u`.`estado` = 'Activo' ORDER BY `u`.`nivel` DESC, `u`.`nombre` ASC ;

